+const FIXTURE_CONTROL_MODE: &str = "LAMP_EXPRESSION_FIXTURE_CONTROL";
+const FIXTURE_CONTROL_VARIANT: &str = "LAMP_EXPRESSION_FIXTURE_VARIANT";
+const FIXTURE_CONTROL_WITNESS: &str = "fixture/setup_expiry";
+
+fn fixture_control_configuration() -> Option<(String, String)> {
+    let mode = std::env::var(FIXTURE_CONTROL_MODE).ok()?;
+    let variant = std::env::var(FIXTURE_CONTROL_VARIANT).unwrap();
+    assert!(matches!(mode.as_str(), "setup" | "after_publish"));
+    assert!(matches!(variant.as_str(), "before" | "after"));
+    Some((mode, variant))
+}
+
+fn fixture_control_record(
+    bus: &Bus,
+    case: &str,
+    offline_face: Option<bool>,
+    stage: &str,
+    topic: &str,
+    message: Option<&Message>,
+) {
+    let (mode, variant) = fixture_control_configuration().unwrap();
+    eprintln!(
+        "EXPRESSION_FIXTURE_CONTROL {}",
+        serde_json::json!({
+            "case": case,
+            "offline_face": offline_face,
+            "mode": mode,
+            "variant": variant,
+            "stage": stage,
+            "root": bus.root().to_string_lossy(),
+            "topic": topic,
+            "wall_ms": runtime::unix_ms(),
+            "grace_ms": lamp_bus::EXPIRY_GRACE_MS,
+            "header": message.map(|message| &message.header),
+            "expired": message.map(|message| message.expired),
+            "payload_utf8": message.map(|message| {
+                std::str::from_utf8(&message.payload).unwrap()
+            }),
+        })
+    );
+}
+
+fn fixture_control_snapshot(
+    bus: &Bus,
+    case: &str,
+    offline_face: Option<bool>,
+    stage: &str,
+    topic: &str,
+) -> Option<Message> {
+    let message = bus.latest(topic).unwrap();
+    fixture_control_record(bus, case, offline_face, stage, topic, message.as_ref());
+    message
+}
+
+fn fixture_control_until_expired(
+    bus: &Bus,
+    case: &str,
+    offline_face: Option<bool>,
+    topic: &str,
+    first: &Message,
+) -> Message {
+    assert!(!first.expired, "control started with expired input");
+    assert_eq!(first.header.expires_ms, Some(500));
+    assert_eq!(lamp_bus::EXPIRY_GRACE_MS, 50);
+    let began = std::time::Instant::now();
+    loop {
+        assert!(
+            began.elapsed() < std::time::Duration::from_secs(4),
+            "control expiry watchdog elapsed"
+        );
+        let message = bus.latest(topic).unwrap().unwrap();
+        assert_eq!(message.header, first.header, "control header changed");
+        assert_eq!(message.payload, first.payload, "control payload changed");
+        if message.expired {
+            assert!(began.elapsed() < std::time::Duration::from_secs(4));
+            assert!(message.header.expired_at(runtime::unix_ms()));
+            fixture_control_record(
+                bus,
+                case,
+                offline_face,
+                "expiry_observed",
+                topic,
+                Some(&message),
+            );
+            return message;
+        }
+        // Poll the actual expiry condition; this delay is not completion.
+        std::thread::sleep(std::time::Duration::from_millis(1));
+    }
+}
+
+fn fixture_control_after_setup(bus: &Bus, case: &str, offline_face: Option<bool>) {
+    let Some((mode, variant)) = fixture_control_configuration() else {
+        return;
+    };
+    if mode != "setup" {
+        let _ = fixture_control_snapshot(
+            bus,
+            case,
+            offline_face,
+            "setup_not_delayed",
+            VoiceTiming::TOPIC,
+        );
+        return;
+    }
+    let first = fixture_control_snapshot(
+        bus,
+        case,
+        offline_face,
+        "setup_input_before",
+        VoiceTiming::TOPIC,
+    );
+    if variant == "before" {
+        assert!(!first.as_ref().unwrap().expired);
+    } else {
+        assert!(first.is_none(), "new setup already had voice input");
+    }
+    let mut witness = bus
+        .publisher_declared(
+            FIXTURE_CONTROL_WITNESS,
+            &VoiceTiming::declaration(),
+            "fixture",
+        )
+        .unwrap();
+    witness.publish_json(5, &voice(10_000_000)).unwrap();
+    let timed = fixture_control_snapshot(
+        bus,
+        case,
+        offline_face,
+        "witness_fresh",
+        FIXTURE_CONTROL_WITNESS,
+    )
+    .unwrap();
+    fixture_control_until_expired(bus, case, offline_face, FIXTURE_CONTROL_WITNESS, &timed);
+    let after = fixture_control_snapshot(
+        bus,
+        case,
+        offline_face,
+        "setup_input_after",
+        VoiceTiming::TOPIC,
+    );
+    if let Some(first) = first {
+        let after = after.unwrap();
+        assert_eq!(after.header, first.header);
+        assert_eq!(after.payload, first.payload);
+        assert!(after.expired, "old actual voice input did not expire");
+    } else {
+        assert!(after.is_none(), "setup created a product input");
+    }
+}
+
+fn fixture_control_before_step(bus: &Bus, case: &str, offline_face: Option<bool>) {
+    let Some((mode, variant)) = fixture_control_configuration() else {
+        return;
+    };
+    let first = fixture_control_snapshot(
+        bus,
+        case,
+        offline_face,
+        "step_input_before",
+        VoiceTiming::TOPIC,
+    )
+    .unwrap();
+    let expire_now = mode == "after_publish" && offline_face != Some(false);
+    let message = if expire_now {
+        fixture_control_until_expired(bus, case, offline_face, VoiceTiming::TOPIC, &first)
+    } else {
+        assert_eq!(first.expired, mode == "setup" && variant == "before");
+        first
+    };
+    fixture_control_record(
+        bus,
+        case,
+        offline_face,
+        "pre_step_guard",
+        VoiceTiming::TOPIC,
+        Some(&message),
+    );
+}

